static long sum(long n){long s=0;if(n<=0)return 0;__asm__("1:\n\taddq %%rcx, %0\n\tloop 1b" : "+r"(s), "+c"(n));return s;}static int zero(long n){int r=1;__asm__("jrcxz 1f\n\tmovl $0, %0\n1:" : "+r"(r) : "c"(n));return r;}static long both(long n){long s=0;__asm__("jrcxz 2f\n1:\n\tincq %0\n\tloop 1b\n2:" : "+r"(s), "+c"(n));return s;}static int over(long n){int r=0;__asm__("jrcxz 2f\n1:\n\tincl %0\n\tcmpl $5, %0\n\tje 2f\n\tloop 1b\n2:" : "+r"(r), "+c"(n));return r;}int tested(int n){long m=(long)((unsigned)n%9u);return (int)sum(m+1)+zero(m)*3+zero(0)*5+(int)both(m)*7+(int)both(0)*11+over(m)*13+over(0)*17;}